import heapq
import itertools


def _temporal_solver(minimum_duration, exact_coupons):
    def solve(data):
        required = data.get("required", [])
        full_mask = (1 << len(required)) - 1
        visit_masks = [0] * data["n"]
        for index, node in enumerate(required):
            visit_masks[node] |= 1 << index

        source = data["source"]
        initial_mask = visit_masks[source]
        initial_used = 0
        start = data["start"]
        initial_state = (source, initial_mask, initial_used)
        distances = {initial_state: start}
        queue = [(start, source, initial_mask, initial_used)]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        coupon_limit = data["coupons"]
        while queue:
            arrival, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if distances.get(state) != arrival:
                continue
            if (node == data["target"] and mask == full_mask and
                    (used == coupon_limit if exact_coupons else used <= coupon_limit)):
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                # close is exclusive for departures; arrival may exceed close.
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < coupon_limit:
                    discounted = max(minimum_duration,
                                     edge["duration"] - edge.get("discount", 0))
                    options.append((discounted, used + 1))
                next_node = edge["v"]
                next_mask = mask | visit_masks[next_node]
                for duration, next_used in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (next_node, next_mask, next_used)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node,
                                                next_mask, next_used))
        return {"arrival": None}
    return solve


def _component_06(data):
    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        rank = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or rank > chosen[event_id][0]:
            chosen[event_id] = (rank, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), mode)
        tax = rounded(net * event.get("tax_bp", 0), mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = (event.get("account", "default") + "|" +
               event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    packages = data["packages"]
    all_names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    root_ranges = {name: [tuple(bounds)]
                   for name, bounds in data["roots"].items()}
    best_vector = None
    best_versions = None

    def acyclic(graph):
        done = set()
        active = set()

        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            for other in graph.get(name, ()):
                if not visit(other):
                    return False
            active.remove(name)
            done.add(name)
            return True

        return all(visit(name) for name in graph)

    def search(versions, ranges, graph):
        nonlocal best_vector, best_versions
        for name, version in versions.items():
            if any(not low <= version <= high
                   for low, high in ranges.get(name, ())):
                return

        unresolved = [name for name in ranges if name not in versions]
        if not unresolved:
            if not acyclic(graph):
                return
            vector = tuple(versions.get(name, -1) for name in all_names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(versions)
            return

        name = min(unresolved)
        pin = pins.get(name)
        for row in packages.get(name, []):
            version = row["version"]
            if version in blocked.get(name, []):
                continue
            if pin is not None and version != pin:
                continue
            if any(not low <= version <= high
                   for low, high in ranges.get(name, ())):
                continue

            next_versions = dict(versions)
            next_versions[name] = version
            next_ranges = {key: list(value) for key, value in ranges.items()}
            next_graph = {key: list(value) for key, value in graph.items()}
            dependencies = [dep for dep in row.get("deps", [])
                            if not dep.get("feature") or
                            dep["feature"] in features]
            next_graph[name] = []
            valid = True
            for dep in dependencies:
                dep_name = dep["name"]
                next_ranges.setdefault(dep_name, []).append(
                    (dep["min"], dep["max"]))
                next_graph[name].append(dep_name)
                if dep_name in next_versions and not (
                        dep["min"] <= next_versions[dep_name] <= dep["max"]):
                    valid = False
            if valid:
                search(next_versions, next_ranges, next_graph)

    search({}, root_ranges, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _component_08(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_value = None
    best_ids = None

    if not mandatory.issubset({job["id"] for job in jobs}):
        return {"error": "impossible"}

    for subset in itertools.combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        ends = []
        fits = True
        for job in sorted(subset, key=lambda item: (item["start"], item["end"])):
            while ends and ends[0] <= job["start"]:
                heapq.heappop(ends)
            heapq.heappush(ends, job["end"])
            if len(ends) > 2:
                fits = False
                break
        if not fits:
            continue

        value = sum(job["value"] for job in subset)
        ordered_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and ordered_ids > best_ids)):
            best_value = value
            best_ids = ordered_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


SOLVERS = {
    "component_01": _temporal_solver(1, True),
    "component_02": _temporal_solver(2, False),
    "component_03": _temporal_solver(2, True),
    "component_04": _temporal_solver(1, False),
    "component_05": _temporal_solver(1, True),
    "component_06": _component_06,
    "component_07": _component_07,
    "component_08": _component_08,
}
